{'role': 'user', 'content': [{'tool_use_id': 'toolu_01JZoSkXWtB2dD8a32T5ts1Y', 'type': 'tool_result', 'content': '     1→/** M7 Event Detection types — mirrors Python MusicalEvent and DrumPattern. */
     2→
     3→export interface MusicalEvent {
     4→  type: EventType;
     5→  timestamp: number; // seconds from track start
     6→  duration: number | null; // null for instantaneous events
     7→  intensity: number; // 0.0–1.0
     8→  payload: Record<string, unknown>;
     9→}
    10→
    11→export type EventType =
    12→  | "kick"
    13→  | "snare"
    14→  | "hihat"
    15→  | "clap"
    16→  | "riser"
    17→  | "faller"
    18→  | "stab";
    19→
    20→export interface DrumPattern {
    21→  bar_start: number;
    22→  bar_end: number;
    23→  kick: number[]; // 16 slots per bar (1=hit, 0=silent)
    24→  snare: number[];
    25→  clap: number[];
    26→  hihat_type: "8ths" | "16ths" | "offbeat" | "roll" | "none";
    27→  hihat_density: number; // 0.0–1.0
    28→  hihat_open_ratio: number;
    29→  confidence: number;
    30→}
    31→
    32→export interface TrackEventsResponse {
    33→  fingerprint: string;
    34→  events: MusicalEvent[];
    35→  drum_patterns: DrumPattern[];
    36→  total_events: number;
    37→  total_patterns: number;
    38→  event_types: EventType[];
    39→}
    40→
    41→/** Color mapping for event types on the timeline. */
    42→export const EVENT_COLORS: Record<EventType, string> = {
    43→  kick: "#ef4444",    // red
    44→  snare: "#f97316",   // orange
    45→  clap: "#eab308",    // yellow
    46→  hihat: "#84cc16",   // lime
    47→  riser: "#06b6d4",   // cyan
    48→  faller: "#8b5cf6",  // violet
    49→  stab: "#ec4899",    // pink
    50→};
    51→
    52→/** Section background colors (muted, for context bands). */
    53→export const SECTION_COLORS: Record<string, string> = {
    54→  intro: "rgba(148, 163, 184, 0.15)",
    55→  verse: "rgba(96, 165, 250, 0.15)",
    56→  build: "rgba(251, 191, 36, 0.15)",
    57→  drop: "rgba(239, 68, 68, 0.15)",
    58→  breakdown: "rgba(167, 139, 250, 0.15)",
    59→  outro: "rgba(148, 163, 184, 0.15)",
    60→};
    61→'}]}

