{'role': 'user', 'content': [{'tool_use_id': 'toolu_019rLuQjfBJhvbsMiWWyfG17', 'type': 'tool_result', 'content': '     1→/**
     2→ * DetectorTuningPage — dev-only page for testing and tuning event detection.
     3→ *
     4→ * Route: /dev/detectors
     5→ * Loads a track's analysis, displays detected events on the waveform,
     6→ * and provides controls for filtering, toggling, and comparing strategies.
     7→ */
     8→
     9→import { useState, useCallback, useMemo } from "react";
    10→import { useQuery } from "@tanstack/react-query";
    11→import { TrackPicker } from "../components/analysis/TrackPicker.tsx";
    12→import { EventTimeline } from "../components/detectors/EventTimeline.tsx";
    13→import { EventControls } from "../components/detectors/EventControls.tsx";
    14→import { EventStats } from "../components/detectors/EventStats.tsx";
    15→import type { EventType, MusicalEvent, TrackEventsResponse } from "../types/events.ts";
    16→
    17→const API_BASE = "/api/tracks";
    18→
    19→const ALL_TYPES: EventType[] = ["kick", "snare", "clap", "hihat", "riser", "faller", "stab"];
    20→
    21→export function DetectorTuningPage() {
    22→  const [fingerprint, setFingerprint] = useState<string | null>(null);
    23→  const [visibleTypes, setVisibleTypes] = useState<Set<EventType>>(new Set(ALL_TYPES));
    24→  const [minConfidence, setMinConfidence] = useState(0);
    25→
    26→  // Fetch track analysis
    27→  const { data: analysis, isLoading: analysisLoading } = useQuery({
    28→    queryKey: ["track", fingerprint],
    29→    queryFn: async () => {
    30→      const res = await fetch(`${API_BASE}/${fingerprint}`);
    31→      if (!res.ok) throw new Error("Track not found");
    32→      return res.json();
    33→    },
    34→    enabled: !!fingerprint,
    35→  });
    36→
    37→  // Fetch events
    38→  const { data: eventsData, isLoading: eventsLoading } = useQuery<TrackEventsResponse>({
    39→    queryKey: ["track-events", fingerprint],
    40→    queryFn: async () => {
    41→      const res = await fetch(`${API_BASE}/${fingerprint}/events`);
    42→      if (!res.ok) throw new Error("Events not found");
    43→      return res.json();
    44→    },
    45→    enabled: !!fingerprint,
    46→  });
    47→
    48→  // Expand drum patterns into MusicalEvent[] for timeline display
    49→  const allEvents: MusicalEvent[] = useMemo(() => {
    50→    if (!eventsData) return [];
    51→
    52→    const tonal = eventsData.events ?? [];
    53→
    54→    // Expand patterns into kick/snare/clap events
    55→    const percussion: MusicalEvent[] = [];
    56→    if (analysis?.downbeats && analysis.beats && eventsData.drum_patterns) {
    57→      const beats = analysis.beats as number[];
    58→      const downbeats = analysis.downbeats as number[];
    59→      const avgBeatDur =
    60→        beats.length >= 2 ? (beats[beats.length - 1] - beats[0]) / (beats.length - 1) : 0.5;
    61→      const sixteenthDur = avgBeatDur / 4;
    62→
    63→      for (const pattern of eventsData.drum_patterns) {
    64→        for (let bar = pattern.bar_start; bar < pattern.bar_end; bar++) {
    65→          if (bar >= downbeats.length) break;
    66→          const barTime = downbeats[bar];
    67→          const localBar = bar - pattern.bar_start;
    68→          const slotOffset = localBar * 16;
    69→
    70→          for (let slot = 0; slot < 16; slot++) {
    71→            const absSlot = slotOffset + slot;
    72→            const t = barTime + slot * sixteenthDur;
    73→
    74→            if (absSlot < pattern.kick.length && pattern.kick[absSlot]) {
    75→              percussion.push({ type: "kick", timestamp: t, duration: null, intensity: 0.8, payload: {} });
    76→            }
    77→            if (absSlot < pattern.snare.length && pattern.snare[absSlot]) {
    78→              percussion.push({ type: "snare", timestamp: t, duration: null, intensity: 0.7, payload: {} });
    79→            }
    80→            if (absSlot < pattern.clap.length && pattern.clap[absSlot]) {
    81→              percussion.push({ type: "clap", timestamp: t, duration: null, intensity: 0.6, payload: {} });
    82→            }
    83→          }
    84→        }
    85→      }
    86→    }
    87→
    88→    return [...tonal, ...percussion].sort((a, b) => a.timestamp - b.timestamp);
    89→  }, [eventsData, analysis]);
    90→
    91→  const duration = analysis?.duration ?? 0;
    92→  const sections = analysis?.sections ?? [];
    93→  const totalBars = analysis?.downbeats?.length ?? 0;
    94→
    95→  const handleToggleType = useCallback((type: EventType) => {
    96→    setVisibleTypes((prev) => {
    97→      const next = new Set(prev);
    98→      if (next.has(type)) next.delete(type);
    99→      else next.add(type);
   100→      return next;
   101→    });
   102→  }, []);
   103→\

{'role': 'user', 'content': [{'tool_use_id': 'toolu_014UULxs4Wpf4BXkbMUQjv7c', 'type': 'tool_result', 'content': '     1→/**
     2→ * EventTimeline — waveform canvas with event markers overlaid.
     3→ *
     4→ * Renders detected events on top of the track waveform:
     5→ * - Kicks: vertical red lines
     6→ * - Snares/claps: colored markers
     7→ * - Risers/fallers: shaded horizontal regions
     8→ * - Stabs: short colored bars
     9→ * - Section labels as background color bands
    10→ */
    11→
    12→import { useRef, useEffect, useCallback } from "react";
    13→import type { MusicalEvent, EventType } from "../../types/events";
    14→import { EVENT_COLORS, SECTION_COLORS } from "../../types/events";
    15→
    16→interface Section {
    17→  label: string;
    18→  start: number;
    19→  end: number;
    20→}
    21→
    22→interface Waveform {
    23→  low: number[];
    24→  mid: number[];
    25→  high: number[];
    26→  sample_rate: number;
    27→  duration: number;
    28→}
    29→
    30→interface EventTimelineProps {
    31→  events: MusicalEvent[];
    32→  sections: Section[];
    33→  waveform: Waveform | null;
    34→  duration: number;
    35→  visibleTypes: Set<EventType>;
    36→  minConfidence: number;
    37→  /** Viewport in seconds */
    38→  viewStart: number;
    39→  viewEnd: number;
    40→}
    41→
    42→export function EventTimeline({
    43→  events,
    44→  sections,
    45→  waveform,
    46→  duration,
    47→  visibleTypes,
    48→  minConfidence,
    49→  viewStart,
    50→  viewEnd,
    51→}: EventTimelineProps) {
    52→  const canvasRef = useRef<HTMLCanvasElement>(null);
    53→
    54→  const draw = useCallback(() => {
    55→    const canvas = canvasRef.current;
    56→    if (!canvas) return;
    57→    const ctx = canvas.getContext("2d");
    58→    if (!ctx) return;
    59→
    60→    const rect = canvas.getBoundingClientRect();
    61→    const dpr = window.devicePixelRatio || 1;
    62→    canvas.width = rect.width * dpr;
    63→    canvas.height = rect.height * dpr;
    64→    ctx.scale(dpr, dpr);
    65→
    66→    const w = rect.width;
    67→    const h = rect.height;
    68→    const viewDuration = viewEnd - viewStart;
    69→
    70→    // Helper: time → x
    71→    const timeToX = (t: number) => ((t - viewStart) / viewDuration) * w;
    72→
    73→    // Clear
    74→    ctx.fillStyle = "#0f172a"; // slate-900
    75→    ctx.fillRect(0, 0, w, h);
    76→
    77→    // Draw section background bands
    78→    for (const section of sections) {
    79→      if (section.end < viewStart || section.start > viewEnd) continue;
    80→      const x1 = Math.max(0, timeToX(section.start));
    81→      const x2 = Math.min(w, timeToX(section.end));
    82→      ctx.fillStyle = SECTION_COLORS[section.label] ?? "rgba(100, 100, 100, 0.1)";
    83→      ctx.fillRect(x1, 0, x2 - x1, h);
    84→
    85→      // Section label
    86→      ctx.fillStyle = "rgba(255, 255, 255, 0.3)";
    87→      ctx.font = "10px sans-serif";
    88→      ctx.fillText(section.label, x1 + 4, 12);
    89→    }
    90→
    91→    // Draw waveform — Pioneer-style single blended bar per column
    92→    // Color = frequency ratio (R=low, G=mid, B=high), height = amplitude
    93→    if (waveform && waveform.low.length > 0) {
    94→      const samplesPerSec = waveform.sample_rate;
    95→      const centerY = h * 0.5;
    96→
    97→      const startSample = Math.max(0, Math.floor(viewStart * samplesPerSec));
    98→      const endSample = Math.min(waveform.low.length, Math.ceil(viewEnd * samplesPerSec));
    99→      const sampleCount = endSample - startSample;
   100→
   101→      if (sampleCount > 0) {
   102→        const samplesPerPixel = sampleCount / w;
   103→
   104→        if (samplesPerPixel <= 1) {
   105→          // One bar per sample
   106→          for (let i = startSample; i < endSample; i++) {
   107→            const lo = waveform.low[i] ?? 0;
   108→            const mid_ = waveform.mid[i] ?? 0;
   109→            const hi = waveform.high[i] ?? 0;
   110→            const amplitude = Math.max(lo, mid_, hi);
   111→            if (amplitude < 0.001) continue;
   112→
   113→            const r = Math.min(255, Math.round((lo / amplitude) * 255));
   114→            const g = Math.min(255, Math.round((mid_ / amplitude) * 255));
   115→            const b = Math.min(255, Math.round((hi / amplitude) * 255));
   116→            const barH = amplitude * centerY;
   117→            const x = ((i - startSample) / sampleCount) * w;
   118→            const barWidth = Math.max(1, w / sampleCount);
