{'role': 'user', 'content': [{'tool_use_id': 'toolu_01XEMKtXSd5iSggRWNq9fNXb', 'type': 'tool_result', 'content': '     1→/**
     2→ * EventControls — toggles, confidence slider, and strategy selector.
     3→ *
     4→ * Dev-facing controls for the detector tuning page.
     5→ */
     6→
     7→import type { EventType } from "../../types/events";
     8→import { EVENT_COLORS } from "../../types/events";
     9→
    10→const ALL_EVENT_TYPES: EventType[] = [
    11→  "kick",
    12→  "snare",
    13→  "clap",
    14→  "hihat",
    15→  "riser",
    16→  "faller",
    17→  "stab",
    18→];
    19→
    20→interface EventControlsProps {
    21→  visibleTypes: Set<EventType>;
    22→  onToggleType: (type: EventType) => void;
    23→  minConfidence: number;
    24→  onConfidenceChange: (value: number) => void;
    25→}
    26→
    27→export function EventControls({
