{'role': 'user', 'content': [{'tool_use_id': 'toolu_01TWqAFnBZhXNvRSYuVV3gTY', 'type': 'tool_result', 'content': '     1→/**
     2→ * EventStats — per-event-type counts, density, and average confidence.
     3→ */
     4→
     5→import type { MusicalEvent, EventType } from "../../types/events";
     6→import { EVENT_COLORS } from "../../types/events";
     7→
     8→interface EventStatsProps {
     9→  events: MusicalEvent[];
    10→  totalBars: number;
    11→  duration: number;
    12→}
    13→
    14→interface TypeStats {
    15→  count: number;
    16→  avgIntensity: number;
    17→  eventsPerBar: number;
    18→}
    19→
    20→export function EventStats({ events, totalBars, duration }: EventStatsProps) {
    21→  // Group by type
    22→  const byType = new Map<EventType, MusicalEvent[]>();
    23→  for (const e of events) {
    24→    const list = byType.get(e.type) ?? [];
    25→    list.push(e);
    26→    byType.set(e.type, list);
    27→  }
    28→
    29→  const stats: [EventType, TypeStats][] = [];
    30→  for (const [type, typeEvents] of byType) {
    31→    const avgIntensity =
    32→      typeEvents.reduce((sum, e) => sum + e.intensity, 0) / typeEvents.length;
    33→    stats.push([
    34→      type,
    35→      {
    36→        count: typeEvents.length,
    37→        avgIntensity,
    38→        eventsPerBar: totalBars > 0 ? typeEvents.length / totalBars : 0,
    39→      },
    40→    ]);
    41→  }
    42→
    43→  // Sort by count descending
    44→  stats.sort((a, b) => b[1].count - a[1].count);
    45→
    46→  return (
    47→    <div>
    48→      <h3 className="text-sm font-medium text-slate-400 mb-2">Detection Stats</h3>
    49→      <div className="text-xs text-slate-500 mb-3">
    50→        {events.length} events · {totalBars} bars · {duration.toFixed(1)}s
    51→      </div>
    52→      <div className="space-y-1.5">
    53→        {stats.map(([type, s]) => (
    54→          <div
    55→            key={type}
    56→            className="flex items-center justify-between text-xs font-mono"
    57→          >
    58→            <div className="flex items-center gap-2">
    59→              <span
    60→                className="w-2 h-2 rounded-full"
    61→                style={{ backgroundColor: EVENT_COLORS[type] }}
    62→              />
    63→              <span className="text-slate-300">{type}</span>
    64→            </div>
    65→            <div className="flex gap-4 text-slate-500">
    66→              <span>{s.count}</span>
    67→              <span>{s.eventsPerBar.toFixed(1)}/bar</span>
    68→              <span>{(s.avgIntensity * 100).toFixed(0)}%</span>
    69→            </div>
    70→          </div>
    71→        ))}
    72→        {stats.length === 0 && (
    73→          <div className="text-slate-600 text-xs italic">No events detected</div>
    74→        )}
    75→      </div>
    76→    </div>
    77→  );
    78→}
    79→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01S4wFqW51hCeZkFisTM8urJ', 'type': 'tool_result', 'content': '     1→import { useEffect, useState } from "react";
     2→import { useQueryClient } from "@tanstack/react-query";
     3→import { useAnalyzeStore } from "../../stores/analyzeStore";
     4→import { scanDirectory, startBatchAnalysis, useJobStatus } from "../../api/analyze";
     5→import { FolderBrowser } from "../shared/FolderBrowser";
     6→
     7→export function AnalyzePanel() {
     8→  const store = useAnalyzeStore();
     9→  const { data: job, error: jobError } = useJobStatus(store.jobId);
    10→  const queryClient = useQueryClient();
    11→  const [browserOpen, setBrowserOpen] = useState(false);
    12→
    13→  // Auto-refresh track list when job completes, then auto-dismiss
    14→  useEffect(() => {
    15→    if (job?.status === "complete" || job?.status === "failed") {
    16→      queryClient.invalidateQueries({ queryKey: ["tracks"] });
    17→      const timer = setTimeout(() => store.reset(), 2000);
    18→      return () => clearTimeout(timer);
    19→    }
    20→  }, [job?.status, queryClient, store]);
    21→
    22→  const handleScan = async () => {
    23→    if (!store.scanPath.trim()) return;
    24→    store.setIsScanning(true);
    25→    store.setScanError(null);
    26→    try {
    27→      const result = await scanDirectory(store.scanPath.trim());
    28→      store.setScanResult(result);
    29→    } catch (e) {
    30→      store.setScanError(e instanceof Error ? e.message : String(e));
    31→    } finally {
    32→      store.setIsScanning(false);
    33→    }
    34→  };
    35→
    36→  const handleAnalyze = async () => {
    37→    if (!store.scanResult) return;
    38→    const paths = store.scanResult.new_files.map((f) => f.path);
    39→    try {
    40→      const { job_id } = await startBatchAnalysis(paths);
    41→      store.setJobId(job_id);
    42→    } catch (e) {
    43→      store.setScanError(e instanceof Error ? e.message : String(e));
    44→    }
    45→  };
    46→
    47→  const handleReset = () => {
    48→    store.reset();
    49→  };
    50→
    51→  // Phase 3: Job running or complete (or errored)
    52→  if (store.jobId && (job || jobError)) {
    53→    // Handle polling errors (e.g. server restart, lost job)
    54→    if (jobError && !job) {
    55→      return (
    56→        <div className="mb-6 rounded border border-red-800 bg-red-900/20 p-4">
    57→          <div className="flex items-center justify-between">
    58→            <span className="text-sm text-red-400">
    59→              Analysis job lost — the server may have restarted.
    60→            </span>
    61→            <button
    62→              onClick={handleReset}
    63→              className="text-xs text-gray-400 hover:text-gray-200"
    64→            >
    65→              Dismiss
