{'role': 'user', 'content': [{'tool_use_id': 'toolu_011M5JoLySUejHvppZbuRVzr', 'type': 'tool_result', 'content': '     1→/**
     2→ * DetectorTuningPage — dev-only page for testing and tuning event detection.
     3→ *
     4→ * Route: /dev/detectors
     5→ * Loads a track's analysis, displays detected events on the waveform,
     6→ * and provides controls for filtering, toggling, and comparing strategies.
     7→ */
     8→
     9→import { useState, useCallback, useMemo } from "react";
    10→import { useQuery } from "@tanstack/react-query";
    11→import { TrackPicker } from "../components/analysis/TrackPicker.tsx";
