{'role': 'user', 'content': [{'tool_use_id': 'toolu_01WTKnJRgJV5Zo4PV8H87Ai2', 'type': 'tool_result', 'content': '     1→/**
     2→ * EventStats — per-event-type counts, density, and average confidence.
     3→ */
     4→
     5→import type { MusicalEvent, EventType } from "../../types/events";
     6→import { EVENT_COLORS } from "../../types/events";
     7→
     8→interface EventStatsProps {
     9→  events: MusicalEvent[];
    10→  totalBars: number;
    11→  duration: number;
    12→}
    13→
    14→interface TypeStats {
    15→  count: number;
    16→  avgIntensity: number;
    17→  eventsPerBar: number;
    18→}
    19→
    20→export function EventStats({ events, totalBars, duration }: EventStatsProps) {
    21→  // Group by type
    22→  const byType = new Map<EventType, MusicalEvent[]>();
    23→  for (const e of events) {
    24→    const list = byType.get(e.type) ?? [];
    25→    list.push(e);
    26→    byType.set(e.type, list);
    27→  }
    28→
    29→  const stats: [EventType, TypeStats][] = [];
    30→  for (const [type, typeEvents] of byType) {
    31→    const avgIntensity =
    32→      typeEvents.reduce((sum, e) => sum + e.intensity, 0) / typeEvents.length;
    33→    stats.push([
    34→      type,
    35→      {
    36→        count: typeEvents.length,
    37→        avgIntensity,
    38→        eventsPerBar: totalBars > 0 ? typeEvents.length / totalBars : 0,
    39→      },
    40→    ]);
    41→  }
    42→
    43→  // Sort by count descending
    44→  stats.sort((a, b) => b[1].count - a[1].count);
    45→
    46→  return (
    47→    <div>
    48→      <h3 className="text-sm font-medium text-slate-400 mb-2">Detection Stats</h3>
    49→      <div className="text-xs text-slate-500 mb-3">
    50→        {events.length} events · {totalBars} bars · {duration.toFixed(1)}s
    51→      </div>
    52→      <div className="space-y-1.5">
    53→        {stats.map(([type, s]) => (
    54→          <div
    55→            key={type}
    56→            className="flex items-center justify-between text-xs font-mono"
    57→          >
    58→            <div className="flex items-center gap-2">
    59→              <span
    60→                className="w-2 h-2 rounded-full"
    61→                style={{ backgroundColor: EVENT_COLORS[type] }}
    62→              />
    63→              <span className="text-slate-300">{type}</span>
    64→            </div>
    65→            <div className="flex gap-4 text-slate-500">
    66→              <span>{s.count}</span>
    67→              <span>{s.eventsPerBar.toFixed(1)}/bar</span>
    68→              <span>{(s.avgIntensity * 100).toFixed(0)}%</span>
    69→            </div>
    70→          </div>
    71→        ))}
    72→        {stats.length === 0 && (
    73→          <div className="text-slate-600 text-xs italic">No events detected</div>
    74→        )}
    75→      </div>
    76→    </div>
    77→  );
    78→}
    79→'}]}

